function CastingLadleSkimmerHandleMaker.init() CastingLadleSkimmerHandleMaker.ironStock=14; CastingLadleSkimmerHandleMaker.bronzeStock=12; CastingLadleSkimmerHandleMaker.woodStock=14; CastingLadleSkimmerHandleMaker.leatherStock=8; CastingLadleSkimmerHandleMaker.silverStock=8; CastingLadleSkimmerHandleMaker.goldStock=6; CastingLadleSkimmerHandleMaker.jewelStock=4; CastingLadleSkimmerHandleMaker.pearlStock=4; CastingLadleSkimmerHandleMaker.productStock={}; CastingLadleSkimmerHandleMaker.buildings={}; CastingLadleSkimmerHandleMaker.maker=nil; CastingLadleSkimmerHandleMaker.activeMaking={}; CastingLadleSkimmerHandleMaker.totalProducts=0; CastingLadleSkimmerHandleMaker.dayTimer=0; print("[CastingLadleSkimmerHandleMaker] Royal Casting Ladle Skimmer Handle Maker System initialized (6 products, 4 buildings)") end
