function CastingLadleSkimmerHandleMaker.completeMaking(m) local q=1.0+(CastingLadleSkimmerHandleMaker.getQualityBonus()/100); if CastingLadleSkimmerHandleMaker.maker then q=q+(CastingLadleSkimmerHandleMaker.maker.skill/140) end; q=math.min(2.5,q); CastingLadleSkimmerHandleMaker.productStock[m.productType]=(CastingLadleSkimmerHandleMaker.productStock[m.productType] or 0)+m.quantity; CastingLadleSkimmerHandleMaker.totalProducts=CastingLadleSkimmerHandleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CastingLadleSkimmerHandleMaker.maker then CastingLadleSkimmerHandleMaker.maker.itemsMade=CastingLadleSkimmerHandleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CastingLadleSkimmerHandleMaker.maker.skill=math.min(100,CastingLadleSkimmerHandleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rocaj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"castingladleskimmerhandle.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
